<script setup lang="ts">import{computed}from'vue';import type{TrafficMapFeature}from'../types';const props=defineProps<{feature:TrafficMapFeature}>();defineEmits<{close:[]}>();const isSection=computed(()=>props.feature.objectType==='road-section');const rows=computed(()=>Object.entries(props.feature.properties).filter(([key])=>!['trafficFeature','__layerName','sourceLayer','sectionId','NAME'].includes(key)));const progress=computed(()=>String(props.feature.properties['建设进度']||'0%'))</script>
<template><article><button class="close" aria-label="关闭详情" @click="$emit('close')">×</button><header><div><small>{{isSection?'施工标段概览':'空间要素详情'}}</small><b>{{feature.name}}</b></div><span>{{feature.status||'正常'}}</span></header><template v-if="isSection"><div class="progress"><div><span>建设进度</span><b>{{progress}}</b></div><i><em :style="{width:progress}"></em></i></div><div class="metrics"><span><b>{{feature.properties['线路长度']||'--'}}</b><small>线路长度</small></span><span><b>{{feature.properties['环保问题']||'--'}}</b><small>环保问题</small></span><span><b>{{feature.properties['风险点']||'--'}}</b><small>风险点</small></span></div></template><dl><template v-for="([key,value]) in rows" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd></template></dl><footer v-if="isSection">演示补充资料 · 可在接入正式项目数据后替换</footer></article></template>
<style scoped>article{position:relative;width:300px;padding:14px;background:linear-gradient(145deg,rgba(4,28,48,.97),rgba(3,15,29,.96));border:1px solid rgba(28,194,230,.55);box-shadow:0 12px 35px rgba(0,0,0,.42);color:#d9f1ff}.close{position:absolute;right:8px;top:7px;width:25px;height:25px;padding:0!important;border:0!important;background:transparent!important;color:#7ba8ba!important;font-size:20px;line-height:24px}.close:hover{color:#fff!important}header{display:flex;justify-content:space-between;align-items:center;padding:0 32px 10px 0;border-bottom:1px solid rgba(45,172,207,.24)}header small,header b{display:block}header small{margin-bottom:4px;color:#5ba4bd;font-size:9px}header b{font-size:16px}header>span{padding:3px 8px;color:#52e3a4;background:rgba(27,176,114,.12);border:1px solid rgba(46,213,145,.3);font-size:10px}.progress{padding:12px 0}.progress>div{display:flex;justify-content:space-between;font-size:11px}.progress>div span{color:#7fa2b3}.progress>div b{color:#2bd9f4}.progress>i{display:block;height:5px;margin-top:6px;background:#0c3146}.progress em{display:block;height:100%;background:linear-gradient(90deg,#126ed1,#23ddf3)}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.metrics span{padding:8px 4px;text-align:center;background:rgba(10,58,82,.48);border:1px solid rgba(45,151,191,.2)}.metrics b,.metrics small{display:block}.metrics b{font-size:12px}.metrics small{margin-top:4px;color:#6f94a6;font-size:9px}dl{display:grid;grid-template-columns:82px 1fr;margin:10px 0 0;font-size:10px}dt,dd{padding:4px 2px;border-bottom:1px solid rgba(67,117,139,.12)}dt{color:#6f93ac}dd{margin:0;color:#bdd2dc}footer{margin-top:9px;color:#52788b;font-size:9px}</style>
